  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      rId <= 6'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_ar_valid) begin
        rId <= s_axi_ar_bits_id;
      end else begin
        rId <= 6'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      rBurst <= 2'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_ar_valid) begin
        rBurst <= s_axi_ar_bits_burst;
      end else begin
        rBurst <= 2'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      rSize <= 3'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_ar_valid) begin
        rSize <= s_axi_ar_bits_size;
      end else begin
        rSize <= 3'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      leftLen <= 8'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_ar_valid) begin
        leftLen <= s_axi_ar_bits_len;
      end
    end else if (!(2'h1 == state)) begin 
      if (2'h2 == state) begin 
        if (~ready) begin
          leftLen <= _leftLen_T_2;
        end else begin
          leftLen <= _GEN_22;
        end
      end else if (2'h3 == state) begin 
        leftLen <= _GEN_29;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      iAddr <= 18'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_ar_valid) begin 
        iAddr <= s_axi_ar_bits_addr; 
      end
    end else if (2'h1 == state) begin 
      if (ready) begin 
        if (!(leftLen == 8'h0)) begin 
          iAddr <= NextAddr;
        end
      end
    end else if (2'h2 == state) begin 
      if (!(~ready)) begin
        iAddr <= _GEN_21;
      end
    end else if (2'h3 == state) begin 
      iAddr <= _GEN_30;
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      Stream_data_reg <= 128'h0; 
    end else if (~SpadState) begin
      Stream_data_reg <= data;
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      SpadState <= 1'h0; 
    end else if (~SpadState) begin 
      if (_s_axi_ar_ready_T | _valid_T_1) begin 
        SpadState <= 1'h0; 
      end else begin
        SpadState <= _GEN_52; 
      end
    end else if (SpadState) begin 
      if (_s_axi_ar_ready_T) begin
        SpadState <= 1'h0;
      end else if (s_axi_r_ready) begin
        SpadState <= 1'h0;
      end
    end
