module SramArbiter(
  input        wrvalid, 
  output       wrready, 
  input        rdvalid, 
  output       rdready, 
  input  [3:0] wr_cs, 
  input  [3:0] rd_cs 
);
  assign wrready = wr_cs == rd_cs & wrvalid & rdvalid | wrvalid; 
  assign rdready = wr_cs == rd_cs & wrvalid & rdvalid ? 1'h0 : rdvalid; 
endmodule
