module ShiftRightJam(
  input  [25:0] io_in, 
  input  [7:0]  io_shamt, 
  output [25:0] io_out, 
  output        io_sticky 
);
  wire  exceed_max_shift = io_shamt > 8'h1a; 
  wire [4:0] shamt = io_shamt[4:0]; 
  wire [31:0] _sticky_mask_T = 32'h1 << shamt; 
  wire [31:0] _sticky_mask_T_2 = _sticky_mask_T - 32'h1; 
  wire [25:0] _sticky_mask_T_5 = exceed_max_shift ? 26'h3ffffff : 26'h0; 
  wire [25:0] sticky_mask = _sticky_mask_T_2[25:0] | _sticky_mask_T_5; 
  wire [25:0] _io_out_T = io_in >> io_shamt; 
  wire [25:0] _io_sticky_T = io_in & sticky_mask; 
  assign io_out = exceed_max_shift ? 26'h0 : _io_out_T; 
  assign io_sticky = |_io_sticky_T; 
endmodule
