  reg [9:0] reservedBits; 
  wire [9:0] _freeBits_T_1 = 10'h200 - validBits; 
  wire [9:0] freeBits = _freeBits_T_1 - reservedBits; 
  wire  _canPull_T_1 = freeBits >= 10'h80; 
  wire  canPull = state == 2'h1 & freeBits >= 10'h80; 
