  wire [1150:0] _GEN_24 = {{639'd0}, dataReg}; 
  wire [1150:0] withNew = _GEN_24 | _withNew_T; 
  wire [1150:0] _dataReg_T = {{48'd0}, withNew[1150:48]}; 
  wire [511:0] _dataReg_T_3 = {{48'd0}, dataReg[511:48]}; 
