  wire [9:0] _GEN_29 = {{4'd0}, decVal}; 
  wire [9:0] _validBits_T_3 = _validBits_T_1 - _GEN_29; 
  wire [9:0] _GEN_30 = {{2'd0}, incRes}; 
  wire [9:0] _reservedBits_T_1 = reservedBits + _GEN_30; 
