      end
    `endif
    `endif // SYNTHESIS
    `ifndef SYNTHESIS
    `ifdef PRINTF_COND
      if (`PRINTF_COND) begin
    `endif
        if (_T_13 & ~(reservedBits <= 10'h200)) begin
          $fwrite(32'h80000002,"Assertion failed\n    at ConfigController.scala:161 assert(reservedBits <= ACC_W.U)\n"); 
        end
    `ifdef PRINTF_COND
      end
    `endif
    `endif // SYNTHESIS
    `ifndef SYNTHESIS
    `ifdef STOP_COND
      if (`STOP_COND) begin
    `endif
        if (_T_13 & ~(reservedBits <= 10'h200)) begin
          $fatal; 
        end
    `ifdef STOP_COND
      end
    `endif
    `endif // SYNTHESIS
    `ifndef SYNTHESIS
    `ifdef PRINTF_COND
      if (`PRINTF_COND) begin
    `endif
        if (_T_13 & ~(_T_20 <= 10'h200)) begin
          $fwrite(32'h80000002,
            "Assertion failed: dataReg overflow: insufficient free bits before issuing SRAM read.\n    at ConfigController.scala:162 assert((validBits + reservedBits) <= ACC_W.U,\n"
