    `ifdef PRINTF_COND
      end
    `endif
    `endif // SYNTHESIS
    `ifndef SYNTHESIS
    `ifdef STOP_COND
      if (`STOP_COND) begin
    `endif
        if (_T_13 & ~(_T_20 <= 10'h200)) begin
          $fatal; 
        end
    `ifdef STOP_COND
      end
    `endif
    `endif // SYNTHESIS
    `ifndef SYNTHESIS
    `ifdef PRINTF_COND
      if (`PRINTF_COND) begin
    `endif
        if (canPull & _T_13 & ~_canPull_T_1) begin
          $fwrite(32'h80000002,
            "Assertion failed: Read issued without guaranteeing enough buffer space.\n    at ConfigController.scala:165 assert(freeBits >= dataWidthSram.U,\n"
